const question =
  $('When chat message received').first().json.chatInput;

const chunks = items.map((item, index) => {
  const document = item.json.document ?? {};
  const metadata = document.metadata ?? {};

  return {
    rank: index + 1,
    score: item.json.score ?? null,
    page_content: document.pageContent ?? '',
    document_id: metadata.document_id ?? '',
    title: metadata.title ?? '',
    source_file: metadata.source_file ?? '',
    source_url: metadata.source_url ?? ''
  };
});

const context = chunks
  .map(chunk => [
    `[Source: ${chunk.source_file}]`,
    `Title: ${chunk.title}`,
    `File: ${chunk.source_file}`,
    `Score: ${chunk.score}`,
    `Content:`,
    chunk.page_content
  ].join('\n'))
  .join('\n\n---\n\n');

const sources = [
  ...new Map(
    chunks.map(chunk => [
      chunk.source_file,
      {
        document_id: chunk.document_id,
        title: chunk.title,
        source_file: chunk.source_file,
        source_url: chunk.source_url
      }
    ])
  ).values()
];

return [{
  json: {
    question,
    context,
    sources,
    chunks,
    retrieval_count: chunks.length,
    top_score: chunks[0]?.score ?? 0
  }
}];
